#repTable{table-layout:fixed}#repTable caption{text-align:start;padding:2px 2px 6px}#repTable th,#repTable td{padding:7px 2px;white-space:normal}#repTable th:first-child,#repTable td:first-child{min-width:0;overflow-wrap:anywhere;padding-inline-start:6px}
#repTable .c2{width:60px}#repTable .c3{width:40px}#repTable .c4{width:44px}#repTable .c5{width:82px}.rp-n{font-weight:700;line-height:1.25}.rp-m{display:block;font-size:11px;color:var(--muted);font-family:ui-monospace,Menlo,monospace}
.rp-s{display:inline-flex;align-items:center;min-height:32px;margin:0 6px 6px 0;padding:0 12px;border:1px solid var(--line);border-radius:999px;background:none;color:inherit;font:inherit;font-size:13px;font-weight:650;cursor:pointer}.rp-s.on{background:var(--ink);border-color:var(--ink);color:var(--card,#fff)}
.rp-b{height:4px;border-radius:3px;background:var(--line);margin:3px 4px 0;overflow:hidden}.rp-b i{display:block;height:100%;background:var(--acc)}td.capc .rp-b i{background:var(--bad)}.rp-u{display:inline-block;min-width:24px;border-radius:7px;padding:1px 5px;font-weight:800}.rp-u.on{background:var(--bad-soft);color:var(--bad)}
